# Search for key patterns indicating the grader output, checkpoints, and final grade
for pat in ["checkpoint", "GRADE", "fail", "c_m18", "milestone", "phi", "STATUS", "GIVE_UP", "final", "grad"]:
    res = await CONTEXT.search(pat)
    matches = res.get('matches', [])
    if matches:
        print(f"\n--- '{pat}': {len(matches)} matches ---")
        for m in matches[:8]:
            # Get more context around this match
            snippet = m['snippet']
            print(f"  [{m['offset']}]: {repr(snippet[:250])}")
